select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"epionce","slug":"rapid-recovery-treatment-kit","title_zh_hk":"\u5feb\u901f\u4fee\u5fa9\u7642\u6548\u7d44\u5408","title_zh_cn":"\u5feb\u901f\u4fee\u590d\u7597\u6548\u7ec4\u5408","title_en":"Rapid Recovery Treatment Kit","description_zh_hk":"<p>\u5feb\u901f\u7642\u6548\u4fee\u5fa9\u7d44\u5408\u5c08\u70ba\u7642\u7a0b\u4e4b\u5f8c\u4e4b\u4fee\u5fa9\u800c\u7814\u88fd\uff0c\u80fd\u4ee4\u63a5\u53d7\u7642\u7a0b\u5f8c\u53d7\u5275\u50b7\u4e4b\u808c\u819a\u52a0\u901f\u5fa9\u539f\uff0c\u6e1b\u5c11\u7642\u7a0b\u5e36\u4f86\u7684\u4e0d\u9069\u53ca\u6709\u52a9\u964d\u7d05\u3002\u6b64\u5957\u88dd\u80fd\u4fee\u5fa9\u53d7\u640d\u7684\u808c\u819a\u4fdd\u8b77\u5c64\uff0c\u540c\u6642\u6709\u4fdd\u6fd5\u53ca\u93ae\u975c\uff0c\u654f\u611f\u808c\u819a\u7684\u529f\u6548\u3002</p>\n\n<p><u>\u6ecb\u6f64\u6f54\u9762\u4e73</u></p>\n<p>\u6ecb\u6f64\u6f54\u9762\u4e73\u6709\u6548\u6eab\u548c\u5730\u5378\u599d\uff0c\u6eb6\u89e3\u6c61\u67d3\u7269\u3001\u7d30\u83cc\u3001\u5875\u57a2\u53ca\u5176\u4ed6\u96dc\u8cea\u3002\u9019\u6b3e\u8212\u7de9\u6f54\u9762\u4e73\u6df1\u5c64\u6e05\u6f54\u9762\u90e8\uff0c\u800c\u4e14\u4e0d\u640d\u5bb3\u808c\u819a\u4fdd\u8b77\u5c64\u529f\u80fd\uff0c\u4ea6\u4e0d\u6703\u523a\u6fc0\u6216\u4ee4\u808c\u819a\u4e7e\u71e5\u3002</p>\n\n<p><u>\u6f64\u6fa4\u7dca\u7dfb\u9762\u819c</u></p>\n<p>\u7279\u5f37\u4fdd\u6fd5\u9762\u819c\u5feb\u901f\u4fee\u5fa9\u53ca\u5f37\u5316\u808c\u819a\u4fdd\u8b77\u5c64\uff0c\u63d0\u5347\u808c\u819a\u5f48\u6027\u53ca\u7dca\u7dfb\u5ea6\u3002\u7522\u54c1\u4e2d\u860a\u542b\u9ad8\u6548\u6ecb\u6f64\u808c\u819a\u7684\u795e\u7d93\u905e\u8cea\uff0c\u76ae\u5c64\u8102\u8cea\uff0c\u6297\u6c27\u5316\u690d\u7269\u7cbe\u83ef\u53ca\u5f37\u6548\u4fdd\u6fd5\u5291\u3002</p>\n\n<p><u>\u8212\u7de9\u4fee\u5fa9\u7cbe\u6cb9</u></p>\n<p>\u542b\u5929\u7136\u6297\u708e\u53ca\u6297\u83cc\u6210\u4efd\uff0c\u6709\u6548\u70ba\u654f\u611f\u808c\u819a\u88dc\u6c34\u3002</p>\n\n<p><u>\u518d\u751f\u8b77\u808c\u93ae\u975c\u971c</u></p>\n<p>\u518d\u751f\u8b77\u808c\u93ae\u975c\u971cRenewal Calming Cream\uff0c\u662fEpionce\u7522\u54c1\u7cfb\u5217\u4e2d\u7b2c\u4e00\u6b3e\u6839\u64da\u7f8e\u570b\u98df\u54c1\u53ca\u85e5\u7269\u7ba1\u7406\u5c40\uff08FDA\uff09\u76ae\u819a\u4fdd\u8b77\u5c08\u984c\u800c\u7814\u767c\u7684\u6fd5\u75b9\u975e\u8655\u65b9\u76ae\u819a\u7522\u54c1 \u3002\u518d\u751f\u8b77\u808c\u93ae\u975c\u971c\u80fd\u512a\u5316\u53ca\u6062\u5fa9\u808c\u819a\u4fdd\u8b77\u5c4f\u969c\u7684\u542b\u6c34\u91cf\uff0c\u6709\u6548\u7de9\u89e3\u6fd5\u75b9\u548c\u808c\u819a\u4e7e\u71e5\u7b49\u9811\u56fa\u75c7\u72c0\u3002\u81e8\u5e8a\u7814\u7a76\u986f\u793a\u4e86\u518d\u751f\u8b77\u808c\u93ae\u975c\u971c\u70ba\u6fd5\u75b9\u75c7\u72c0\u63d0\u4f9b\u5fc5\u8981\u7684\u8212\u7de9\u3002</p>","description_zh_cn":"<p>\u5feb\u901f\u7597\u6548\u4fee\u590d\u7ec4\u5408\u4e13\u4e3a\u7597\u7a0b\u4e4b\u540e\u4e4b\u4fee\u590d\u800c\u7814\u5236\uff0c\u80fd\u4ee4\u63a5\u53d7\u7597\u7a0b\u540e\u53d7\u521b\u4f24\u4e4b\u808c\u80a4\u52a0\u901f\u590d\u539f\uff0c\u51cf\u5c11\u7597\u7a0b\u5e26\u6765\u7684\u4e0d\u9002\u53ca\u6709\u52a9\u964d\u7ea2\u3002\u6b64\u5957\u88c5\u80fd\u4fee\u590d\u53d7\u635f\u7684\u808c\u80a4\u4fdd\u62a4\u5c42\uff0c\u540c\u65f6\u6709\u4fdd\u6e7f\u53ca\u9547\u9759\uff0c\u654f\u611f\u808c\u80a4\u7684\u529f\u6548\u3002</p>\n\n<p><u>\u6ecb\u6da6\u6d01\u9762\u4e73</u></p>\n<p>\u6ecb\u6da6\u6d01\u9762\u4e73\u6709\u6548\u6e29\u548c\u5730\u5378\u5986\uff0c\u6eb6\u89e3\u6c61\u67d3\u7269\u3001\u7ec6\u83cc\u3001\u5c18\u57a2\u53ca\u5176\u4ed6\u6742\u8d28\u3002\u8fd9\u6b3e\u8212\u7f13\u6d01\u9762\u4e73\u6df1\u5c42\u6e05\u6d01\u9762\u90e8\uff0c\u800c\u4e14\u4e0d\u635f\u5bb3\u808c\u80a4\u4fdd\u62a4\u5c42\u529f\u80fd\uff0c\u4ea6\u4e0d\u4f1a\u523a\u6fc0\u6216\u4ee4\u808c\u80a4\u5e72\u71e5\u3002</p>\n\n<p><u>\u6da6\u6cfd\u7d27\u81f4\u9762\u819c</u></p>\n<p>\u7279\u5f3a\u4fdd\u6e7f\u9762\u819c\u5feb\u901f\u4fee\u590d\u53ca\u5f3a\u5316\u808c\u80a4\u4fdd\u62a4\u5c42\uff0c\u63d0\u5347\u808c\u80a4\u5f39\u6027\u53ca\u7d27\u81f4\u5ea6\u3002\u4ea7\u54c1\u4e2d\u8574\u542b\u9ad8\u6548\u6ecb\u6da6\u808c\u80a4\u7684\u795e\u7ecf\u9012\u8d28\uff0c\u76ae\u5c42\u8102\u8d28\uff0c\u6297\u6c27\u5316\u690d\u7269\u7cbe\u534e\u53ca\u5f3a\u6548\u4fdd\u6e7f\u5242\u3002</p>\n\n<p><u>\u8212\u7f13\u4fee\u590d\u7cbe\u6cb9</u></p>\n<p>\u542b\u5929\u7136\u6297\u708e\u53ca\u6297\u83cc\u6210\u4efd\uff0c\u6709\u6548\u4e3a\u654f\u611f\u808c\u80a4\u8865\u6c34\u3002</p>\n\n<p><u>\u518d\u751f\u62a4\u808c\u9547\u9759\u971c</u></p>\n<p>\u518d\u751f\u62a4\u808c\u9547\u9759\u971cRenewal Calming Cream\uff0c\u662fEpionce\u4ea7\u54c1\u7cfb\u5217\u4e2d\u7b2c\u4e00\u6b3e\u6839\u636e\u7f8e\u56fd\u98df\u54c1\u53ca\u836f\u7269\u7ba1\u7406\u5c40\uff08FDA\uff09\u76ae\u80a4\u4fdd\u62a4\u4e13\u9898\u800c\u7814\u53d1\u7684\u6e7f\u75b9\u975e\u5904\u65b9\u76ae\u80a4\u4ea7\u54c1 \u3002\u518d\u751f\u62a4\u808c\u9547\u9759\u971c\u80fd\u4f18\u5316\u53ca\u6062\u590d\u808c\u80a4\u4fdd\u62a4\u5c4f\u969c\u7684\u542b\u6c34\u91cf\uff0c\u6709\u6548\u7f13\u89e3\u6e7f\u75b9\u548c\u808c\u80a4\u5e72\u71e5\u7b49\u987d\u56fa\u75c7\u72b6\u3002\u4e34\u5e8a\u7814\u7a76\u663e\u793a\u4e86\u518d\u751f\u62a4\u808c\u9547\u9759\u971c\u4e3a\u6e7f\u75b9\u75c7\u72b6\u63d0\u4f9b\u5fc5\u8981\u7684\u8212\u7f13\u3002</p>","description_en":"<p>Formulated for post-treatment recovery: helps skin heal faster, reduces discomfort and redness, restores the barrier, hydrates and calms sensitive skin.</p>\n<p><u>Gentle Cream Cleanser</u></p>\n<p>Gently removes makeup, pollutants, bacteria and dirt without compromising the barrier or drying the skin.</p>\n<p><u>Hydrating Firming Mask</u></p>\n<p>Intensive hydration to restore and strengthen the barrier, improving elasticity and firmness.</p>\n<p><u>Soothing Repair Oil</u></p>\n<p>Natural anti-inflammatory and antibacterial actives to hydrate sensitive skin.</p>\n<p><u>Renewal Calming Cream</u></p>\n<p>Epionce's first OTC eczema product developed to the FDA skin-protectant monograph. Optimises barrier hydration and clinically soothes eczema and dryness.</p>","price_hkd":395,"stock":20,"image_paths":["/images/products/prod-13@2x.jpg"],"sort":217}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;